begin;
set local lock_timeout='5s';set local statement_timeout='60s';
do $$ begin if public.operations_feature_state('MAINTENANCE')<>'MAINTENANCE' then raise exception 'MAINTENANCE_REQUIRED';end if;end $$;
create temp table rollout_preserved_before on commit drop as select jsonb_build_object('users',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select jsonb_build_array(to_jsonb(t)->'id',to_jsonb(t)->'cash',to_jsonb(t)->'neon_diamonds',to_jsonb(t)->'vitality',to_jsonb(t)->'pvp_points',to_jsonb(t)->'raid_points') v from public.users t) s),'user_characters',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select jsonb_build_array(to_jsonb(t)->'id',to_jsonb(t)->'user_id',to_jsonb(t)->'character_id',to_jsonb(t)->'level',to_jsonb(t)->'plus_val') v from public.user_characters t) s),'user_skills',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select jsonb_build_array(to_jsonb(t)->'id',to_jsonb(t)->'user_id',to_jsonb(t)->'skill_id',to_jsonb(t)->'plus_val') v from public.user_skills t) s),'user_equipments',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select jsonb_build_array(to_jsonb(t)->'id',to_jsonb(t)->'user_id',to_jsonb(t)->'equipment_id',to_jsonb(t)->'level',to_jsonb(t)->'plus_val') v from public.user_equipments t) s),'user_items',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select jsonb_build_array(to_jsonb(t)->'user_id',to_jsonb(t)->'item_id',to_jsonb(t)->'quantity') v from public.user_items t) s),'feature_operating_states',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select to_jsonb(t) v from public.feature_operating_states t) s),'ranking_seasons',(select md5(coalesce(jsonb_agg(v order by v::text)::text,'[]')) from (select to_jsonb(t) v from public.ranking_seasons t) s)) as signature;

